={{ JSON.stringify({
  model: 'gpt-4o',
  tools: [{ type: 'web_search' }],
  input: "Search the web for one notable, recent (within the last few days) international or national news story that is commonly relevant to general knowledge sections of competitive exams in Bangladesh (like BCS) — e.g. international relations, global organizations, science/tech breakthroughs, economy, notable appointments/awards, treaties, summits. You MUST base the post strictly on what your web search actually returns — do not add any claim, quote, or detail that isn't directly supported by the search results. Then write a Bengali Facebook post (150-250 words) explaining the news in your own words and why it matters for GK preparation, with an engaging emoji headline and 3-5 relevant hashtags at the end. IMPORTANT OUTPUT RULES: Respond with ONLY the final Facebook post text itself — no preamble, no 'I searched and found', no 'here is a draft', no explanations, no separators, no citation markdown links in the body. Start your response directly with the emoji headline and end with the hashtags. Plain text only." + ($json.avoidList ? ('\n\nAvoid repeating these recently covered topics: ' + $json.avoidList) : '')
}) }}

parameters.jsCode:
const output = $json.output || [];
const msg = output.find(o => o.type === 'message');
let text = '';
let citations = [];
if (msg) {
  for (const c of msg.content) {
    if (c.type === 'output_text') {
      text = c.text;
      citations = (c.annotations || []).filter(a => a.type === 'url_citation').map(a => a.url);
    }
  }
}
citations = [...new Set(citations)];
// strip any inline markdown-style links the model added despite instructions
text = text.replace(/\(\[[^\]]*\]\([^)]*\)\)/g, '').replace(/\[[^\]]*\]\(([^)]*)\)/g, '$1');
text = text.replace(/[ \t]+\n/g, '\n').replace(/\n{3,}/g, '\n\n').trim();
let fullMessage = text;
if (citations.length) {
  fullMessage += '\n\nসূত্র: ' + citations[0];
}
const staticData = $getWorkflowStaticData('global');
if (!Array.isArray(staticData.recentTopics)) staticData.recentTopics = [];
const headlineLine = text.split('\n')[0];
staticData.recentTopics.push(headlineLine);
if (staticData.recentTopics.length > 10) staticData.recentTopics = staticData.recentTopics.slice(-10);
return { json: { message: fullMessage, hasCitation: citations.length > 0 } };
